function Show-NetworkDiagnostics {Show-Header;Write-Host "DIAGNOSTICO DE REDE" -ForegroundColor Yellow;try{Get-NetAdapter|Where-Object Status -eq Up|Select-Object Name,LinkSpeed,MacAddress|Format-Table -AutoSize;Get-NetIPConfiguration|Where-Object IPv4Address|Format-List InterfaceAlias,IPv4Address,IPv4DefaultGateway,DNSServer;Test-Connection 1.1.1.1 -Count 4|Select-Object Address,ResponseTime,Status|Format-Table -AutoSize;Resolve-DnsName cloudflare.com|Select-Object Name,Type,IPAddress|Format-Table -AutoSize}catch{Write-Status "Alguns testes falharam." Yellow};Pause-WinOptimizer}
function Clear-DnsCache {Show-Header;if(-not(Confirm-WinOptimizerAction "Limpar cache DNS?")){return};Clear-DnsClientCache;ipconfig /flushdns|Out-Null;Write-Status "Cache DNS limpo." Green;Save-AppliedChange Rede "Cache DNS" "Flush DNS executado.";Pause-WinOptimizer}
function Set-PreferredDns {Show-Header;Write-Host "[1] Cloudflare  [2] Google  [3] Automatico";$c=Read-Host "Opcao";$a=Get-NetAdapter|Where-Object{$_.Status -eq "Up" -and $_.HardwareInterface};switch($c){"1"{$d=@("1.1.1.1","1.0.0.1");$n="Cloudflare"};"2"{$d=@("8.8.8.8","8.8.4.4");$n="Google"};"3"{$d=$null;$n="Automatico"};default{Pause-WinOptimizer;return}};if(-not(Confirm-WinOptimizerAction "Aplicar DNS $n?")){return};foreach($x in $a){if($null -eq $d){Set-DnsClientServerAddress -InterfaceIndex $x.ifIndex -ResetServerAddresses}else{Set-DnsClientServerAddress -InterfaceIndex $x.ifIndex -ServerAddresses $d}};Write-Status "DNS configurado: $n" Green;Save-AppliedChange Rede DNS $n;Pause-WinOptimizer}
function Reset-NetworkConfiguration {Show-Header;Write-Host "Winsock/IP/DNS serao redefinidos. Reinicie depois.";if(-not(Confirm-WinOptimizerAction "Continuar?")){return};netsh winsock reset|Out-Host;netsh int ip reset|Out-Host;ipconfig /flushdns|Out-Host;Write-Status "Rede redefinida. Reinicie o PC." Green;Save-AppliedChange Rede "Reset de rede" "Winsock, IP e DNS redefinidos.";Pause-WinOptimizer}